create extension if not exists pgcrypto;
create extension if not exists citext;
create type public.member_role as enum ('owner','admin','manager','seller');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,locale text not null default 'ru',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role public.member_role not null default 'seller',created_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,email citext not null,role public.member_role not null,token_hash text not null,expires_at timestamptz not null,accepted_at timestamptz,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,sku text not null,name text not null,category text,description text,specifications jsonb not null default '{}',packaging text,min_order numeric check(min_order>0),currency text not null default 'RUB',stock_status text,lead_time text,payment_terms text,max_discount numeric not null default 0,min_price numeric,benefits text[],limitations text[],analog_skus text[],related_skus text[],competitor_differences text[],forbidden_promises text[],is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,sku));
create table public.product_price_tiers(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,min_quantity numeric not null check(min_quantity>0),price numeric not null check(price>=0),unique(product_id,min_quantity));
create table public.company_sales_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,rules jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.buyer_personas(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,public_data jsonb not null default '{}',secret_data jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.training_scenarios(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,persona_id uuid references public.buyer_personas(id),title text not null,channel text not null,difficulty text not null,mode text not null default 'training',settings jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.training_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scenario_id uuid not null references public.training_scenarios(id),user_id uuid not null references public.profiles(id),assigned_by uuid references public.profiles(id),due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.training_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scenario_id uuid references public.training_scenarios(id),user_id uuid not null references public.profiles(id),provider text not null default 'scenario',status text not null default 'active',language text not null default 'ru',started_at timestamptz not null default now(),ended_at timestamptz,sync_version bigint not null default 1);
create table public.session_messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.training_sessions(id) on delete cascade,role text not null check(role in ('buyer','seller')),content text not null,created_at timestamptz not null default now());
create table public.session_state(session_id uuid primary key references public.training_sessions(id) on delete cascade,encrypted_state text not null,updated_at timestamptz not null default now());
create table public.evaluations(id uuid primary key default gen_random_uuid(),session_id uuid not null unique references public.training_sessions(id) on delete cascade,total_score int not null check(total_score between 0 and 100),outcome text,summary jsonb not null default '{}',created_at timestamptz not null default now());
create table public.evaluation_criteria(id uuid primary key default gen_random_uuid(),evaluation_id uuid not null references public.evaluations(id) on delete cascade,criterion text not null,score int not null,max_score int not null,evidence jsonb not null default '[]',recommendation text);
create table public.coaching_recommendations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id),session_id uuid references public.training_sessions(id),content jsonb not null,created_at timestamptz not null default now());
create table public.skill_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id),skill text not null,score numeric not null,session_id uuid references public.training_sessions(id),created_at timestamptz not null default now());
create table public.ai_usage_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid references public.profiles(id),provider text not null,operation text not null,status text not null,tokens int default 0,created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references public.profiles(id),action text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index products_org_search_idx on public.products using gin(to_tsvector('simple',coalesce(sku,'')||' '||coalesce(name,'')||' '||coalesce(description,'')));
create index sessions_user_started_idx on public.training_sessions(user_id,started_at desc);create index messages_session_created_idx on public.session_messages(session_id,created_at);create index skills_user_created_idx on public.skill_history(user_id,created_at desc);
create function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members m where m.organization_id=org and m.user_id=auth.uid())$$;
create function public.has_org_role(org uuid,roles member_role[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members m where m.organization_id=org and m.user_id=auth.uid() and m.role=any(roles))$$;
alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.products enable row level security;alter table public.product_price_tiers enable row level security;alter table public.company_sales_rules enable row level security;alter table public.buyer_personas enable row level security;alter table public.training_scenarios enable row level security;alter table public.training_assignments enable row level security;alter table public.training_sessions enable row level security;alter table public.session_messages enable row level security;alter table public.session_state enable row level security;alter table public.evaluations enable row level security;alter table public.evaluation_criteria enable row level security;alter table public.coaching_recommendations enable row level security;alter table public.skill_history enable row level security;alter table public.ai_usage_events enable row level security;alter table public.audit_events enable row level security;
create policy org_read on public.organizations for select using(public.is_org_member(id));create policy members_read on public.organization_members for select using(public.is_org_member(organization_id));create policy products_member_all on public.products for all using(public.is_org_member(organization_id)) with check(public.has_org_role(organization_id,array['owner','admin','manager']::member_role[]));create policy rules_member_read on public.company_sales_rules for select using(public.is_org_member(organization_id));create policy scenarios_member_read on public.training_scenarios for select using(public.is_org_member(organization_id));create policy sessions_owner_or_manager on public.training_sessions for select using(user_id=auth.uid() or public.has_org_role(organization_id,array['owner','admin','manager']::member_role[]));create policy sessions_owner_insert on public.training_sessions for insert with check(user_id=auth.uid() and public.is_org_member(organization_id));
